Import ListNotations.
Open Scope bv_scope.
Open Scope Z_scope.
#[global] Unset Lia Cache. #[global] Unset Nia Cache. #[global] Unset Nra Cache.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_n8 segs m a bs.
Local Ltac Z.euclidean_division_equations_cleanup ::= idtac.

Section STRCMP.
  Context {HCEIL : HeapCeil}.
  Variables (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : word -> option byte) (e t rest1 rest2 : list Z) (lo : Z).
  Hypothesis E1 : bytes_at asegs m (bv_unsigned a0) (map b8 (e ++ 0 :: rest1)).
  Hypothesis FE : Forall (fun c => 0 < c < 256) e.
  Hypothesis E2 : bytes_at asegs m (bv_unsigned a1) (map b8 (t ++ 0 :: rest2)).
  Hypothesis FT : Forall (fun c => 0 < c < 256) t.
  Hypothesis ACC1 : accessible m (bv_unsigned a0) (Z.of_nat (length e) + 1).
  Hypothesis ACC2 : accessible m (bv_unsigned a1) (Z.of_nat (length t) + 1).
  Hypothesis SV1 : shvis m (bv_unsigned a0) (bv_unsigned a0 + Z.of_nat (length e) + 1).
  Hypothesis SV2 : shvis m (bv_unsigned a1) (bv_unsigned a1 + Z.of_nat (length t) + 1).
  Hypothesis ST0 : stk asegs m lo (bv_unsigned sp).
  Hypothesis CEIL : aceil <= lo.
  Hypothesis LO : lo <= bv_unsigned sp - AINTRIN_STACK.
  Hypothesis MI : mem_inv asegs m.
  Hypothesis AC : ACONST m.
  Hypothesis N40e : Z.of_nat (length e) + 1 <= 2 ^ 40.
  Hypothesis N40t : Z.of_nat (length t) + 1 <= 2 ^ 40.
  Hypothesis INM1 : in_app_mem (bv_unsigned a0) (bv_unsigned a0 + Z.of_nat (length e) + 1).
  Hypothesis INM2 : in_app_mem (bv_unsigned a1) (bv_unsigned a1 + Z.of_nat (length t) + 1).
  Hypothesis DJ1 : bv_unsigned a0 + Z.of_nat (length (e ++ 0 :: rest1)) <= lo \/ bv_unsigned sp <= bv_unsigned a0.
  Hypothesis DJ2 : bv_unsigned a1 + Z.of_nat (length (t ++ 0 :: rest2)) <= lo \/ bv_unsigned sp <= bv_unsigned a1.

  Notation p1 := (bv_unsigned a0).
  Notation p2 := (bv_unsigned a1).
  Notation lne := (Z.of_nat (length e)).
  Notation lnt := (Z.of_nat (length t)).
  Notation POST := (astrcmp_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc lo m).
  Notation SP2 := (Z_to_bv 64 (bv_unsigned sp + -2192)).
  Notation W := [(bv_unsigned sp - 4096, bv_unsigned sp)].

  Notation RST pc x1 x5 x10 x11 x12 x13 x14 x15 x16 x17 x20 x21 x22 x23 x24 x25 x26 x27 mm :=
    (MS (mkR x1 SP2 gp tp x5 t1 t2 sp a1 x10 x11 x12 x13 x14 x15 x16 x17 a0 ra x20 x21 x22 x23 x24 x25 x26 x27 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None mm (seg_rom asegs)).
  Notation FRAME mm := (rw_cells asegs mm (bv_unsigned sp + -104)
                         [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]).

